1	#!/usr/bin/env python3
2	"""OpenSurvey HTTP service."""
3	import argparse
4	import json
5	import re
6	from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
7	from pathlib import Path
8	import signal
9	import sqlite3
10	import threading
11	from urllib.parse import urlsplit
12	
13	PRODUCT = "OpenSurvey"
14	RESOURCE = "surveys"
15	MAX_BODY_BYTES = 10 * 1024 * 1024
16	QUESTION_TYPES = ("text", "single_choice")
17	
18	PAGE = r"""<!doctype html>
19	<html lang="zh-CN">
20	<meta charset="utf-8">
21	<meta name="viewport" content="width=device-width,initial-scale=1">
22	<title>OpenSurvey · 问卷调查与反馈管理</title>
23	<style>
24	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
25	*{box-sizing:border-box}
26	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
27	a{color:var(--blue)}
28	h1{margin-bottom:.2rem}
29	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
30	.muted{color:var(--grey);font-size:.92rem}
31	ul.plain{list-style:none;padding-left:0}
32	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
33	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
34	input[type=text],textarea{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
35	textarea{resize:vertical}
36	/* 标题与选项允许内部换行：用随内容增高的 textarea 展示，不能压成单行输入框 */
37	textarea.grow{resize:none;overflow:hidden;min-height:2.4rem;line-height:1.5}
38	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
39	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
40	.q-index{font-weight:700}
41	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
42	.tag.required{background:#fdecea;color:var(--red)}
43	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
44	.spacer{flex:1}
45	button{font:inherit;cursor:pointer}
46	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
47	.btn.secondary{background:#fff;color:var(--blue)}
48	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
49	.link.danger{color:var(--red)}
50	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
51	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
52	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
53	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
54	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
55	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
56	/* 保存状态条：与错误提示条区分开，明确“刚才那次提交已保存”与“还有未保存修改” */
57	.save-status{margin:1rem 0;display:flex;flex-direction:column;gap:.5rem}
58	.save-status[hidden]{display:none}
59	.save-note{border-radius:.5rem;padding:.7rem 1rem;white-space:normal}
60	.save-note.saved{border:1px solid #1e7e45;background:#ecf7f0;color:#155c33}
61	.save-note.dirty{border:1px solid #9a6d12;background:#fdf6e3;color:#7a5207}
62	/* 等待保存结果：蓝色中性提示，与成功（绿）、未保存（黄）、错误（红）区分 */
63	.save-note.saving{border:1px solid var(--blue);background:#eef4fb;color:#144a80}
64	button:disabled{opacity:.55;cursor:not-allowed}
65	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
66	.invalid{border-color:var(--red)!important;background:#fdf6f5}
67	.detail-meta{color:var(--grey);font-size:.9rem}
68	.detail-desc,.opt-text-display{white-space:pre-wrap}
69	/* 标题中被接口保留的内部换行在列表与详情中也要原样显示 */
70	h2,.q-list .q-line,ul.plain a{white-space:pre-wrap}
71	.q-list>li{margin:1rem 0}
72	.q-list .q-line{font-weight:600}
73	.q-list ol{margin:.4rem 0 0 1.4rem}
74	</style>
75	<main>
76	<h1>OpenSurvey</h1>
77	<p>问卷调查与反馈管理</p>
78	<div id="app"></div>
79	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
80	</main>
81	<script>
82	"use strict";
83	const app = document.getElementById("app");
84	
85	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
86	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
87	// 返回也必须丢弃，不能覆盖用户当前所在页面。
88	let activeView = 0;
89	
90	function h(tag, attrs, ...children) {
91	  const el = document.createElement(tag);
92	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
93	    if (v === null || v === undefined) continue;
94	    if (k === "class") el.className = v;
95	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
96	    else el.setAttribute(k, v);
97	  }
98	  for (const child of children.flat()) {
99	    if (child === null || child === undefined) continue;
100	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
101	  }
102	  return el;
103	}
104	
105	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
106	
107	function buildSurveyForm(existing, hooks, view) {
108	  const mode = existing ? "edit" : "create";
109	
110	  const banner = h("div", {class: "banner", id: "form-banner"});
111	  banner.hidden = true;
112	
113	  // 编辑模式下保存结果的状态条：成功保存与“仍有未保存修改”必须分开展示，
114	  // 不能只给一条笼统的“保存成功”。新建模式不使用它（保存成功即进入详情）。
115	  const statusBar = h("div", {class: "save-status", id: "save-status", role: "status"});
116	  statusBar.hidden = true;
117	
118	  const titleInput = h("textarea", {id: "survey-title", rows: "1", class: "grow",
119	    maxlength: "200", placeholder: "请输入问卷标题（可含换行）"});
120	  const titleErr = h("p", {class: "field-err", id: "title-err"});
121	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
122	  const qBox = h("div", {id: "questions"});
123	  const qErr = h("p", {class: "field-err", id: "questions-err"});
124	
125	  function renumber() {
126	    const cards = qBox.querySelectorAll(".q-card");
127	    cards.forEach((card, i) => {
128	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
129	      card.querySelectorAll(".opt-row").forEach((row, j) => {
130	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
131	      });
132	    });
133	  }
134	
135	  // textarea 的高度随内容变化：单行内容外观与原输入框一致，出现内部换行时
136	  // 自动增高，让换行真实可见、可编辑，而不是被折叠或截断。
137	  function autoGrow(el) {
138	    el.style.height = "auto";
139	    el.style.height = `${el.scrollHeight}px`;
140	  }
141	  // 预填值时元素可能还没挂到文档上（scrollHeight 为 0），延到下一帧布局后再量。
142	  function scheduleGrow(el) { requestAnimationFrame(() => autoGrow(el)); }
143	
144	  function optionRow(value) {
145	    const text = h("textarea", {rows: "1", class: "opt-text grow", placeholder: "选项内容（可含换行）"});
146	    text.addEventListener("input", () => autoGrow(text));
147	    if (value !== undefined && value !== null) { text.value = value; scheduleGrow(text); }
148	    const row = h("div", {class: "opt-row"},
149	      h("span", {class: "opt-index"}, "选项"),
150	      text,
151	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
152	    );
153	    return row;
154	  }
155	
156	  function addQuestion(type, prefill) {
157	    const isChoice = type === "single_choice";
158	    const options = h("div", {class: "options"});
159	    const card = h("div", {class: "card q-card", "data-type": type},
160	      h("div", {class: "q-head"},
161	        h("span", {class: "q-index"}, "第 N 题"),
162	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
163	        h("label", {class: "req"},
164	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
165	        h("span", {class: "spacer"}),
166	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
167	      ),
168	      h("textarea", {rows: "1", class: "q-title grow", placeholder: "题目标题（可含换行）"}),
169	      h("p", {class: "field-err q-title-err"})
170	    );
171	    if (isChoice) {
172	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
173	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
174	      else options.append(optionRow(), optionRow());
175	      card.append(
176	        options,
177	        h("p", {class: "field-err opt-err"}),
178	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
179	      );
180	      card.querySelector(".add-opt").addEventListener("click", () => {
181	        options.append(optionRow());
182	        renumber();
183	        options.querySelector(".opt-row:last-child .opt-text").focus();
184	      });
185	    }
186	    const qTitleEl = card.querySelector(".q-title");
187	    qTitleEl.addEventListener("input", () => autoGrow(qTitleEl));
188	    if (prefill) {
189	      qTitleEl.value = prefill.title != null ? prefill.title : "";
190	      card.querySelector(".q-required").checked = !!prefill.required;
191	    }
192	    scheduleGrow(qTitleEl);
193	    qBox.append(card);
194	    renumber();
195	    if (!prefill) qTitleEl.focus();
196	    return card;
197	  }
198	
199	  function clearErrors() {
200	    banner.hidden = true;
201	    banner.replaceChildren();
202	    titleErr.textContent = "";
203	    qErr.textContent = "";
204	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
205	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
206	  }
207	
208	  function hideSaveStatus() {
209	    statusBar.hidden = true;
210	    statusBar.replaceChildren();
211	  }
212	
213	  // 保存成功后：绿色块只陈述“刚才提交的内容已保存”；若等待期间又有修改，
214	  // 再追加一块黄色“当前还有未保存的修改”。两者同时出现、含义互不混淆。
215	  function renderSaveStatus(dirty) {
216	    statusBar.replaceChildren(
217	      h("div", {class: "save-note saved", id: "save-note-saved"},
218	        h("strong", null, "已保存：刚才提交的内容已保存到服务器。")),
219	      dirty
220	        ? h("div", {class: "save-note dirty", id: "save-note-dirty"},
221	            h("strong", null,
222	              "当前还有未保存的修改：页面内容在点击保存后又被改动（等待结果期间的修改不会自动补交）。可继续编辑，并再次点击“保存修改”。"))
223	        : null
224	    );
225	    statusBar.hidden = false;
226	  }
227	
228	  // 一次保存进行中：保存按钮禁用并明确显示“正在保存…”，状态条显示等待提示。
229	  // 在请求有明确结果前，重复点击按钮或用键盘再次提交都不会追加请求，也不会
230	  // 清掉等待提示。等待期间标题、说明、题目、选项、必填与增删操作全部可用。
231	  let saving = false;
232	  function setSavingUI() {
233	    submitButton.disabled = true;
234	    submitButton.textContent = "正在保存…";
235	    statusBar.replaceChildren(
236	      h("div", {class: "save-note saving", id: "save-note-saving", role: "status"},
237	        h("strong", null, "正在保存：正在等待本次保存的结果，请稍候。等待期间仍可继续编辑，这些改动不会自动追加到本次提交。"))
238	    );
239	    statusBar.hidden = false;
240	  }
241	  function resetSaveButton() {
242	    submitButton.disabled = false;
243	    submitButton.textContent = submitButton.getAttribute("data-label");
244	  }
245	
246	  // 按与提交时完全相同的规则读取当前表单：标题/题目标题/选项去掉首尾空白，
247	  // 说明与内部换行原样保留。返回结构可直接做整体相等比较，用来判断“点击保存
248	  // 之后表单是否又被改过”。改过又恢复原值时结构相同，不会被当成有未保存修改。
249	  function currentState() {
250	    return {
251	      title: titleInput.value.trim(),
252	      description: descArea.value,
253	      questions: [...qBox.querySelectorAll(".q-card")].map(card => ({
254	        type: card.dataset.type,
255	        title: card.querySelector(".q-title").value.trim(),
256	        required: card.querySelector(".q-required").checked,
257	        options: [...card.querySelectorAll(".opt-text")].map(el => el.value.trim())
258	      }))
259	    };
260	  }
261	
262	  function sameState(a, b) { return JSON.stringify(a) === JSON.stringify(b); }
263	
264	  function showBanner(items) {
265	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
266	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
267	    banner.hidden = false;
268	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
269	  }
270	
271	  const actionButtons = [
272	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
273	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
274	    h("span", {class: "spacer"})
275	  ];
276	  if (mode === "edit") {
277	    // 离开编辑页即丢弃全部未保存的增删与输入
278	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
279	  }
280	  const submitLabel = mode === "edit" ? "保存修改" : "保存整份问卷";
281	  const submitButton = h("button", {type: "submit", class: "btn", "data-label": submitLabel}, submitLabel);
282	  actionButtons.push(submitButton);
283	
284	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
285	    banner,
286	    statusBar,
287	    h("section", null,
288	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
289	      mode === "edit"
290	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
291	        : null,
292	      h("label", {for: "survey-title"}, "标题"),
293	      titleInput, titleErr,
294	      h("label", {for: "survey-desc"}, "说明"),
295	      descArea,
296	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
297	      qBox, qErr,
298	      h("div", {class: "row-actions"}, actionButtons)
299	    )
300	  );
301	
302	  titleInput.addEventListener("input", () => autoGrow(titleInput));
303	  if (mode === "edit") {
304	    titleInput.value = existing.title != null ? existing.title : "";
305	    descArea.value = existing.description || "";
306	    existing.questions.forEach(question => addQuestion(question.type, question));
307	    renumber();
308	    scheduleGrow(titleInput);
309	
310	    // 最近一次服务器确认保存的表单内容（点击保存时的快照）。它只用于成功返回
311	    // 后判断当前表单相对那次提交有没有新改动；等待期间的输入始终留在表单里，
312	    // 不会被它覆盖，也不会被自动补交。
313	    let savedState = currentState();
314	
315	    function refreshDirty() {
316	      const dirtyNote = statusBar.querySelector("#save-note-dirty");
317	      // 尚未成功保存过（状态条隐藏）时无需提示。
318	      if (statusBar.hidden || !dirtyNote) return;
319	      // 与点击保存时的整份内容比较：改过又恢复原值即视为无未保存修改。
320	      dirtyNote.hidden = sameState(currentState(), savedState);
321	    }
322	
323	    // 监听编辑页上全部真实编辑动作（标题/说明/题目标题/选项输入、必填勾选、
324	    // 题目与选项增删）。题目卡片是动态增删的，因此在表单上做事件委托。
325	    form.addEventListener("input", refreshDirty);
326	    form.addEventListener("change", event => {
327	      if (event.target.closest && event.target.closest(".q-required")) refreshDirty();
328	    });
329	    form.addEventListener("click", event => {
330	      const actionable = event.target.closest
331	        && event.target.closest("button.add-opt, button.link.danger, button.btn.secondary");
332	      if (actionable) {
333	        // 新增/删除在本次点击处理中完成，延到冒泡后再读取最终 DOM。
334	        queueMicrotask(refreshDirty);
335	      }
336	    });
337	
338	    hooks = hooks || {};
339	    hooks.markSaved = state => { savedState = state; };
340	    hooks.isCurrent = state => sameState(currentState(), state);
341	  }
342	
343	  async function submitForm(event) {
344	    event.preventDefault();
345	    // 已有一次保存尚未得到明确结果：忽略后续点击/键盘提交，不追加请求，也不
346	    // 清除正在显示的等待状态。本次保存只代表首次点击时的那份表单快照。
347	    if (saving) return;
348	    clearErrors();
349	    hideSaveStatus();
350	    const problems = [];
351	
352	    const title = titleInput.value.trim();
353	    if (!title) {
354	      titleInput.classList.add("invalid");
355	      titleErr.textContent = "标题不能为空。";
356	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
357	    }
358	
359	    const cards = [...qBox.querySelectorAll(".q-card")];
360	    if (cards.length === 0) {
361	      qErr.textContent = "问卷至少需要保留一道题。";
362	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
363	    }
364	
365	    const payloadQuestions = [];
366	    cards.forEach((card, i) => {
367	      const loc = `第 ${i + 1} 题`;
368	      const titleEl = card.querySelector(".q-title");
369	      const qTitle = titleEl.value.trim();
370	      if (!qTitle) {
371	        titleEl.classList.add("invalid");
372	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
373	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
374	      }
375	      const q = {
376	        type: card.dataset.type,
377	        title: qTitle,
378	        required: card.querySelector(".q-required").checked
379	      };
380	      if (card.dataset.type === "single_choice") {
381	        const optInputs = [...card.querySelectorAll(".opt-text")];
382	        const values = optInputs.map(el => el.value.trim());
383	        const optErr = card.querySelector(".opt-err");
384	        const seen = new Set();
385	        values.forEach((val, j) => {
386	          if (!val) {
387	            optInputs[j].classList.add("invalid");
388	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
389	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
390	          } else if (seen.has(val)) {
391	            optInputs[j].classList.add("invalid");
392	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
393	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
394	          }
395	          seen.add(val);
396	        });
397	        if (values.length < 2) {
398	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
399	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
400	        }
401	        q.options = values;
402	      }
403	      payloadQuestions.push(q);
404	    });
405	
406	    if (problems.length) {
407	      showBanner(problems);
408	      return;
409	    }
410	    // 校验通过、请求即将发出：此后到拿到明确结果前只能有这一次保存进行中。
411	    // 纯客户端校验拒绝不会走到这里，因此不会留下等待状态。
412	    saving = true;
413	    setSavingUI();
414	
415	    const payload = {title, description: descArea.value, questions: payloadQuestions};
416	    // 点击保存这一刻的整份表单快照：这次请求只代表这份内容。成功返回后拿它与
417	    // 当前表单比较——等待期间的任何输入/增删都不属于本次保存。
418	    const submittedState = {
419	      title,
420	      description: descArea.value,
421	      questions: payloadQuestions.map(q => ({
422	        type: q.type, title: q.title, required: q.required, options: q.options || []
423	      }))
424	    };
425	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
426	    // 这次保存只属于发起它的那一代表单；响应再晚返回，只要用户已经离开
427	    // （首页/详情/编辑切换、重新进入同一问卷、浏览器前进后退），其成功或
428	    // 失败结果都必须静默丢弃，不能跳转、清空或提示到当前页面上。
429	    const submitView = view;
430	    let resp;
431	    try {
432	      resp = await fetch(endpoint, {
433	        method: mode === "edit" ? "PUT" : "POST",
434	        headers: {"Content-Type": "application/json"},
435	        body: JSON.stringify(payload)
436	      });
437	    } catch (err) {
438	      if (submitView !== activeView) return;
439	      // 请求未成功：结束等待，保留当前全部输入与增删结果，允许修改后再次保存。
440	      saving = false;
441	      resetSaveButton();
442	      hideSaveStatus();
443	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
444	      return;
445	    }
446	    if (submitView !== activeView) return;
447	    let data = {};
448	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
449	    if (submitView !== activeView) return;
450	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
451	    if (saved && data.id !== undefined) {
452	      if (mode === "create") {
453	        form.reset();
454	        qBox.replaceChildren();
455	        autoGrow(titleInput);
456	        if (hooks && hooks.onCreated) hooks.onCreated();
457	        location.hash = `#/surveys/${data.id}`;
458	        return;
459	      }
460	      // 编辑模式：先把“这次提交的内容”记为已保存（服务器上的草稿正是它）。
461	      if (hooks && hooks.markSaved) hooks.markSaved(submittedState);
462	      // 比较点击保存前后的整份表单：等待期间改过又恢复原值时结构相同，按
463	      // 无新改动处理，仍进入详情。
464	      const stillSame = hooks && hooks.isCurrent ? hooks.isCurrent(submittedState) : true;
465	      if (stillSame) {
466	        location.hash = `#/surveys/${data.id}`;
467	        return;
468	      }
469	      // 等待期间出现了新的修改：留在编辑页，保留当前完整内容与顺序。绿色块
470	      // 只确认“刚才提交的内容已保存”，黄色块提示“当前还有未保存的修改”，
471	      // 不自动补交，也不撤销已成功的保存。保存恢复可用，再次点击提交的才是
472	      // 当前内容，而不是沿用上一笔提交的旧内容。
473	      saving = false;
474	      resetSaveButton();
475	      renderSaveStatus(true);
476	      return;
477	    }
478	    // 服务端未确认保存成功：结束等待，不清空任何输入，展示具体问题；用户修改
479	    // 后可再次保存（不会自行重发，也不会一直停在“正在保存”）。
480	    saving = false;
481	    resetSaveButton();
482	    hideSaveStatus();
483	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
484	  }
485	
486	  return form;
487	}
