755	def main():
756	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
757	    commands = parser.add_subparsers(dest="command", required=True)
758	    serve = commands.add_parser("serve", help="Start the HTTP service")
759	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
760	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
761	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
762	    args = parser.parse_args()
763	    if not 0 <= args.port <= 65535:
764	        parser.error("port must be between 0 and 65535")
765	    args.data_dir.mkdir(parents=True, exist_ok=True)
766	    # 每个连接由独立线程处理（见下方 ThreadingHTTPServer），因此数据库连接
767	    # 会被多个线程共享：check_same_thread=False 允许跨线程使用，所有读写再
768	    # 经 db_lock 串行化，保证一次保存/替换内部的多条语句仍然原子生效。
769	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite", check_same_thread=False)
770	    db_lock = threading.Lock()
771	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
772	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
773	    if "description" not in columns:
774	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
775	    database.execute(
776	        "CREATE TABLE IF NOT EXISTS questions ("
777	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
778	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
779	    )
780	    database.execute(
781	        "CREATE TABLE IF NOT EXISTS question_options ("
782	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
783	    )
784	    database.commit()
785	
786	    def survey_detail(survey_id):
787	        with db_lock:
788	            row = database.execute(
789	                "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
790	                (survey_id,),
791	            ).fetchone()
792	            if row is None:
793	                return None
794	            title, description = row
795	            questions = []
796	            question_rows = database.execute(
797	                "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
798	                (survey_id,),
799	            ).fetchall()
800	            for question_id, question_type, question_title, required in question_rows:
801	                options = [option_row[0] for option_row in database.execute(
802	                    "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
803	                    (question_id,),
804	                )]
805	                questions.append({
806	                    "type": question_type,
807	                    "title": question_title,
808	                    "required": bool(required),
809	                    "options": options,
810	                })
811	        return {
812	            "id": survey_id,
813	            "title": title,
814	            "description": description,
815	            "questions": questions,
816	        }
817	
818	    def save_survey(clean):
819	        """Insert the whole survey atomically; returns the new id."""
820	        with db_lock:
821	            try:
822	                cursor = database.execute(
823	                    "INSERT INTO surveys (title, description) VALUES (?, ?)",
824	                    (clean["title"], clean["description"]),
825	                )
826	                survey_id = cursor.lastrowid
827	                write_questions(survey_id, clean["questions"])
828	                database.commit()
829	                return survey_id
830	            except Exception:
831	                database.rollback()
832	                raise
833	
834	    def write_questions(survey_id, questions):
835	        """Replace all questions/options of a survey with the given ordered list."""
836	        old_question_ids = [row[0] for row in database.execute(
837	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
838	        )]
839	        if old_question_ids:
840	            placeholders = ",".join("?" for _ in old_question_ids)
841	            database.execute(
842	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
843	                old_question_ids,
844	            )
845	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
846	        for position, question in enumerate(questions):
847	            question_cursor = database.execute(
848	                "INSERT INTO questions (survey_id, position, type, title, required) "
849	                "VALUES (?, ?, ?, ?, ?)",
850	                (survey_id, position, question["type"], question["title"],
851	                 1 if question["required"] else 0),
852	            )
853	            question_id = question_cursor.lastrowid
854	            for option_position, option in enumerate(question["options"]):
855	                database.execute(
856	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
857	                    (question_id, option_position, option),
858	                )
859	
860	    def replace_survey(survey_id, clean):
861	        """Replace a whole survey atomically; keeps the same id.
862	
863	        Returns False when the survey does not exist (no record is created).
864	        """
865	        with db_lock:
866	            row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
867	            if row is None:
868	                return False
869	            try:
870	                database.execute(
871	                    "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
872	                    (clean["title"], clean["description"], survey_id),
873	                )
874	                write_questions(survey_id, clean["questions"])
875	                database.commit()
876	                return True
877	            except Exception:
878	                database.rollback()
879	                raise
